-- Run against a NEW Supabase project. All sensitive writes remain RLS-scoped.
create extension if not exists pgcrypto with schema extensions;
create table public.profiles(id uuid primary key references auth.users on delete cascade,display_name text not null check(length(display_name) between 1 and 60),username text unique not null check(username ~ '^[a-z0-9_]{3,24}$'),timezone text not null default 'UTC',notifications_enabled boolean not null default true,created_at timestamptz not null default now());
create table public.connections(requester uuid references public.profiles on delete cascade,recipient uuid references public.profiles on delete cascade,status text not null check(status in ('pending','accepted','blocked')),primary key(requester,recipient),check(requester<>recipient),created_at timestamptz not null default now());
create unique index connections_pair on public.connections(least(requester,recipient),greatest(requester,recipient));
create table public.shared_spaces(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles on delete cascade,name text not null check(length(name) between 1 and 60),created_at timestamptz not null default now());
create table public.shared_space_members(space_id uuid references public.shared_spaces on delete cascade,user_id uuid references public.profiles on delete cascade,primary key(space_id,user_id),created_at timestamptz not null default now());
create table public.space_invitations(id uuid primary key default gen_random_uuid(),space_id uuid not null references public.shared_spaces on delete cascade,token_hash text unique not null,expires_at timestamptz not null default now()+interval '7 days',revoked boolean not null default false,created_at timestamptz not null default now());
create table public.journal_entries(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles on delete cascade,space_id uuid references public.shared_spaces on delete set null,type text not null check(type in ('text','meal','voice','photo','achievement','mood','reflection')),title text not null check(length(title) between 1 and 160),body text not null default '' check(length(body)<=20000),entry_date date not null,metadata jsonb not null default '{}',media_path text,created_at timestamptz not null default now(),check(media_path is null or media_path like owner_id::text||'/%'));
create index entry_owner_date on public.journal_entries(owner_id,entry_date desc);
create index entry_space on public.journal_entries(space_id,created_at desc);
create index membership_user on public.shared_space_members(user_id);
create table public.entry_comments(id uuid primary key default gen_random_uuid(),entry_id uuid not null references public.journal_entries on delete cascade,user_id uuid not null references public.profiles on delete cascade,body text not null check(length(body) between 1 and 2000),created_at timestamptz not null default now());
create table public.entry_reactions(entry_id uuid references public.journal_entries on delete cascade,user_id uuid references public.profiles on delete cascade,emoji text not null check(emoji in ('heart','smile','celebrate')),primary key(entry_id,user_id));
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,title text not null,body text not null default '',read_at timestamptz,created_at timestamptz not null default now());
create table public.game_sessions(id uuid primary key default gen_random_uuid(),space_id uuid not null references public.shared_spaces on delete cascade,owner_id uuid not null references public.profiles on delete cascade,kind text not null check(kind in ('question','know-me')),prompt text not null check(length(prompt) between 1 and 500),created_at timestamptz not null default now());
create table public.game_answers(session_id uuid references public.game_sessions on delete cascade,user_id uuid references public.profiles on delete cascade,answer text not null check(length(answer) between 1 and 2000),primary key(session_id,user_id));
create function public.is_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from shared_space_members where space_id=target and user_id=auth.uid())$$;
create function public.owns_space(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from shared_spaces where id=target and owner_id=auth.uid())$$;
create function public.can_read_entry(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from journal_entries where id=target and (owner_id=auth.uid() or is_member(space_id)))$$;
create function public.can_play(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from game_sessions where id=target and is_member(space_id))$$;
create function public.has_answered(target uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from game_answers where session_id=target and user_id=auth.uid())$$;
alter table public.profiles enable row level security;alter table public.connections enable row level security;alter table public.shared_spaces enable row level security;alter table public.shared_space_members enable row level security;alter table public.space_invitations enable row level security;alter table public.journal_entries enable row level security;alter table public.entry_comments enable row level security;alter table public.entry_reactions enable row level security;alter table public.notifications enable row level security;alter table public.game_sessions enable row level security;alter table public.game_answers enable row level security;
create policy profile_self on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy connection_read on public.connections for select to authenticated using(requester=auth.uid() or recipient=auth.uid());
create policy space_read on public.shared_spaces for select to authenticated using(is_member(id));
create policy members_read on public.shared_space_members for select to authenticated using(is_member(space_id));
create policy invite_owner_read on public.space_invitations for select to authenticated using(owns_space(space_id));
create policy invite_owner_revoke on public.space_invitations for update to authenticated using(owns_space(space_id)) with check(owns_space(space_id));
revoke update on public.space_invitations from authenticated;grant update(revoked) on public.space_invitations to authenticated;
create policy entry_read on public.journal_entries for select to authenticated using(owner_id=auth.uid() or is_member(space_id));
create policy entry_create on public.journal_entries for insert to authenticated with check(owner_id=auth.uid() and (space_id is null or is_member(space_id)));
create policy entry_edit on public.journal_entries for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid() and (space_id is null or is_member(space_id)));
create policy entry_remove on public.journal_entries for delete to authenticated using(owner_id=auth.uid());
create policy comment_read on public.entry_comments for select to authenticated using(can_read_entry(entry_id));
create policy comment_insert on public.entry_comments for insert to authenticated with check(user_id=auth.uid() and can_read_entry(entry_id));
create policy comment_delete on public.entry_comments for delete to authenticated using(user_id=auth.uid());
create policy reaction_read on public.entry_reactions for select to authenticated using(can_read_entry(entry_id));
create policy reaction_insert on public.entry_reactions for insert to authenticated with check(user_id=auth.uid() and can_read_entry(entry_id));
create policy reaction_delete on public.entry_reactions for delete to authenticated using(user_id=auth.uid());
create policy notification_read on public.notifications for select to authenticated using(user_id=auth.uid());
create policy notification_update on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
revoke update on public.notifications from authenticated;grant update(read_at) on public.notifications to authenticated;
create policy game_read on public.game_sessions for select to authenticated using(is_member(space_id));
create policy game_create on public.game_sessions for insert to authenticated with check(owner_id=auth.uid() and is_member(space_id));
create policy answer_read on public.game_answers for select to authenticated using(can_play(session_id) and (user_id=auth.uid() or has_answered(session_id)));
create policy answer_create on public.game_answers for insert to authenticated with check(user_id=auth.uid() and can_play(session_id));
create function public.create_space(space_name text) returns uuid language plpgsql security definer set search_path=public as $$declare new_id uuid;begin if auth.uid() is null then raise exception 'Unauthorized';end if;insert into shared_spaces(owner_id,name) values(auth.uid(),space_name) returning id into new_id;insert into shared_space_members values(new_id,auth.uid(),now());return new_id;end$$;
create function public.create_invitation(target_space uuid) returns text language plpgsql security definer set search_path=public,extensions as $$declare token text;begin if not owns_space(target_space) then raise exception 'Forbidden';end if;token:=encode(gen_random_bytes(32),'hex');insert into space_invitations(space_id,token_hash) values(target_space,encode(digest(token,'sha256'),'hex'));return token;end$$;
create function public.accept_invitation(invite_token text) returns uuid language plpgsql security definer set search_path=public,extensions as $$declare target uuid;begin if auth.uid() is null then raise exception 'Unauthorized';end if;select space_id into target from space_invitations where token_hash=encode(digest(invite_token,'sha256'),'hex') and expires_at>now() and not revoked for update;if target is null then raise exception 'Invitation is invalid or expired';end if;if exists(select 1 from connections c join shared_spaces s on s.id=target where c.status='blocked' and ((c.requester=auth.uid() and c.recipient=s.owner_id) or (c.recipient=auth.uid() and c.requester=s.owner_id))) then raise exception 'Invitation unavailable';end if;insert into shared_space_members(space_id,user_id) values(target,auth.uid()) on conflict do nothing;return target;end$$;
create function public.remove_space_member(target_space uuid,target_member uuid) returns void language plpgsql security definer set search_path=public as $$begin if not owns_space(target_space) and target_member<>auth.uid() then raise exception 'Forbidden';end if;if exists(select 1 from shared_spaces where id=target_space and owner_id=target_member) then raise exception 'The owner cannot be removed';end if;delete from shared_space_members where space_id=target_space and user_id=target_member;end$$;
create function public.find_profile(exact_username text) returns table(id uuid,display_name text,username text) language sql stable security definer set search_path=public as $$select p.id,p.display_name,p.username from profiles p where auth.uid() is not null and p.username=exact_username and not exists(select 1 from connections c where c.status='blocked' and ((c.requester=auth.uid() and c.recipient=p.id) or(c.recipient=auth.uid() and c.requester=p.id))) limit 1$$;
create function public.connection_action(action_name text,target_user uuid) returns void language plpgsql security definer set search_path=public as $$begin if auth.uid() is null or target_user=auth.uid() then raise exception 'Invalid connection';end if;if exists(select 1 from connections where status='blocked' and requester=target_user and recipient=auth.uid()) then raise exception 'Connection unavailable';end if;if action_name='request' then insert into connections(requester,recipient,status) values(auth.uid(),target_user,'pending');insert into notifications(user_id,title,body) values(target_user,'A new connection request','Visit Friends to accept or decline.');elsif action_name='accept' then update connections set status='accepted' where requester=target_user and recipient=auth.uid() and status='pending';elsif action_name='decline' then delete from connections where requester=target_user and recipient=auth.uid() and status='pending';elsif action_name='remove' then delete from connections where ((requester=target_user and recipient=auth.uid()) or (requester=auth.uid() and recipient=target_user)) and (status<>'blocked' or requester=auth.uid());elsif action_name='block' then delete from connections where (requester=target_user and recipient=auth.uid()) or (requester=auth.uid() and recipient=target_user);insert into connections(requester,recipient,status) values(auth.uid(),target_user,'blocked');-- Remove access where blocker owns the space, and leave spaces owned by target.
delete from shared_space_members m using shared_spaces s where m.space_id=s.id and ((s.owner_id=auth.uid() and m.user_id=target_user) or (s.owner_id=target_user and m.user_id=auth.uid()));else raise exception 'Unknown action';end if;end$$;
create function public.entry_notification() returns trigger language plpgsql security definer set search_path=public as $$begin if new.space_id is not null then insert into notifications(user_id,title,body) select m.user_id,'A new shared memory', 'Someone added a moment to your shared space.' from shared_space_members m join profiles p on p.id=m.user_id where m.space_id=new.space_id and m.user_id<>new.owner_id and p.notifications_enabled;end if;return new;end$$;
create trigger entry_notify after insert on public.journal_entries for each row execute function public.entry_notification();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('journal-media','journal-media',false,20971520,array['image/jpeg','image/png','image/webp','image/gif','audio/webm','audio/ogg','audio/mp4','audio/mpeg','audio/wav']);
create policy media_insert on storage.objects for insert to authenticated with check(bucket_id='journal-media' and (storage.foldername(name))[1]=auth.uid()::text);
create policy media_read on storage.objects for select to authenticated using(bucket_id='journal-media' and ((storage.foldername(name))[1]=auth.uid()::text or exists(select 1 from public.journal_entries e where e.media_path=name and public.is_member(e.space_id))));
create policy media_delete on storage.objects for delete to authenticated using(bucket_id='journal-media' and (storage.foldername(name))[1]=auth.uid()::text);
-- Explicitly limit RPC execution; service role is never used for regular user requests.
revoke execute on all functions in schema public from public,anon;
grant execute on function public.is_member(uuid),public.owns_space(uuid),public.can_read_entry(uuid),public.can_play(uuid),public.has_answered(uuid),public.create_space(text),public.create_invitation(uuid),public.accept_invitation(text),public.remove_space_member(uuid,uuid),public.find_profile(text),public.connection_action(text,uuid) to authenticated;
create function public.list_connections() returns table(requester uuid,recipient uuid,status text,display_name text,username text) language sql stable security definer set search_path=public as $$select c.requester,c.recipient,c.status,p.display_name,p.username from connections c join profiles p on p.id=case when c.requester=auth.uid() then c.recipient else c.requester end where c.requester=auth.uid() or c.recipient=auth.uid()$$;
revoke execute on function public.list_connections() from public,anon;
grant execute on function public.list_connections() to authenticated;
